from typing import List


def has_close_elements(numbers: List[float], threshold: float) -> bool:
    numbers = sorted(numbers)
    for i in range(len(numbers) - 1):
        if numbers[i + 1] - numbers[i] < threshold:
            return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    current_group = []
    balance = 0
    for char in paren_string:
        if char == "(":
            balance += 1
            current_group.append(char)
        elif char == ")" and balance > 0:
            balance -= 1
            current_group.append(char)
            if balance == 0:
                groups.append("".join(current_group))
                current_group = []
    return groups

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    mean = sum(numbers) / len(numbers)
    return sum(abs(x - mean) for x in numbers) / len(numbers)

def intersperse(numbers: List[int], delimeter: int) -> List[int]:
    if not numbers:
        return []
    result = []
    for num in numbers[:-1]:
        result.append(num)
        result.append(delimeter)
    result.append(numbers[-1])
    return result

from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def max_nesting(s: str) -> int:
        max_d = cur = 0
        for c in s:
            if c == '(':
                cur += 1
                if cur > max_d:
                    max_d = cur
            elif c == ')':
                cur -= 1
                if cur < 0:
                    return 0
        return max_d if cur == 0 else 0

    result = []
    i = 0
    n = len(paren_string)
    while i < n:
        if paren_string[i] in '()':
            j = i
            while j < n and paren_string[j] in '()':
                j += 1
            depth = max_nesting(paren_string[i:j])
            if depth > 0:
                result.append(depth)
            i = j
        else:
            i += 1
    return result

from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    if not numbers:
        return (0, 1)
    total_sum = sum(numbers)
    product = 1
    for num in numbers:
        product *= num
    return (total_sum, product)

def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []
    result = []
    current_max = float("-inf")
    for num in numbers:
        if num > current_max:
            current_max = num
        result.append(current_max)
    return result

def make_palindrome(string: str) -> str:
    for i in range(len(string)):
        suffix = string[i:]
        if suffix == suffix[::-1]:
            prefix = string[:i]
            return string + prefix[::-1]
    return string

"""Utility for constructing shortest palindromes."""

def make_palindrome(string: str) -> str:
    """Find the shortest palindrome that begins with a supplied string.

    The algorithm locates the longest palindromic suffix of the input and
    appends the reverse of the preceding prefix.
    """
    if not string:
        return string

    n = len(string)
    for start in range(n):
        suffix = string[start:]
        if suffix == suffix[::-1]:
            prefix = string[:start]
            return string + prefix[::-1]
    return string  # fallback (unreachable for non-empty input)

