def parse_music(music_string: str) -> List[int]:
    note_map = {'o': 4, 'o|': 2, '.|': 1}
    notes = music_string.split()
    return [note_map[note] for note in notes]

def how_many_times(string: str, substring: str) -> int:
    if not substring:
        return 0
    count = 0
    start = 0
    while True:
        start = string.find(substring, start)
        if start == -1:
            break
        count += 1
        start += 1
    return count

def sort_numbers(numbers: str) -> str:
    num_dict = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9}
    words = [word for word in numbers.split() if word in num_dict]
    words.sort(key=lambda x: num_dict[x])
    return ' '.join(words)

from typing import List, Tuple

def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    min_diff = float('inf')
    best_i, best_j = 0, 1
    n = len(numbers)
    for i in range(n):
        for j in range(i + 1, n):
            diff = abs(numbers[j] - numbers[i])
            if diff < min_diff or (diff == min_diff and j > best_j):
                min_diff = diff
                best_i, best_j = i, j
    a, b = numbers[best_i], numbers[best_j]
    return (min(a, b), max(a, b)) if a != b else (a, b)

def rescale_to_unit(numbers: List[float]) -> List[float]:
    if len(numbers) < 2:
        return []
    min_val = min(numbers)
    max_val = max(numbers)
    if min_val == max_val:
        return []
    range_val = max_val - min_val
    return [(x - min_val) / range_val for x in numbers]

