def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_zero(xs: List[int]) -> float:
    def p(x): return poly(xs, x)
    lo, hi = -1.0, 1.0
    while p(lo) * p(hi) > 0:
        lo *= 2
        hi *= 2
    for _ in range(100):
        mid = (lo + hi) / 2
        if p(lo) * p(mid) > 0:
            lo = mid
        else:
            hi = mid
    return lo

