    return s[-shift:] + s[:-shift]

def pluck(arr: List[int]) -> List[int]:
    if not arr:
        return []
    smallest_even = None
    idx = -1
    for i, num in enumerate(arr):
        if num % 2 == 0:
            if smallest_even is None or num < smallest_even:
                smallest_even = num
                idx = i
    if smallest_even is None:
        return []
    return [smallest_even, idx]

from typing import List

def search(lst: List[int]) -> int:
    freq = {}
    for num in lst:
        freq[num] = freq.get(num, 0) + 1
    max_val = -1
    for num, count in freq.items():
        if count >= num > max_val:
            max_val = num
    return max_val

import math

def triangle_area(a: int, b: int, c: int) -> float:
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    s = (a + b + c) / 2
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))
    return round(area, 2)

def will_it_fly(q: List[int], w: int) -> bool:
    if not q:
        return 0 <= w
    start = 0
    while start < len(q) and q[start] == 0:
        start += 1
    end = len(q) - 1
    while end >= start and q[end] == 0:
        end -= 1
    if start > end:
        effective = []
    else:
        effective = q[start:end + 1]
    is_pal = effective == effective[::-1]
    total_sum = sum(q)
    return is_pal and total_sum <= w

