def is_simple_power(x: int, n: int) -> bool:
    if x == 1:
        return True
    if n == 1 or n == 0:
        return False
    power = 1
    while power < x:
        try:
            power *= n
        except OverflowError:
            return False
        if power == x:
            return True
    return False

"""
Utility to check if one integer is an integer power of another.
"""

def is_simple_power(x: int, n: int) -> bool:
    """Return True iff x equals n raised to some nonnegative integer power."""
    if x == 0 or n == 0:
        return False
    if x == 1:
        return True
    if n == 1:
        return False

    power = 1
    while power < x:
        power *= n
        if power == x:
            return True
    return False

def iscube(a: int) -> bool:
    root = round(abs(a) ** (1 / 3))
    return root ** 3 == abs(a)

